import {clone,uid,block} from './model.mjs';
import {pageHeight,requiredHeight} from './layout-engine.js';
export function syncPage(d){if(!d.pages)return;const p=d.pages.find(p=>p.id===d.activePageId);if(p)Object.assign(p,{blocks:clone(d.blocks),groups:clone(d.groups||[]),pageHeight:pageHeight(d)});}
export function ensurePages(d){if(!d.pages?.length){const id=uid();d.pages=[{id,name:'Resumo',blocks:clone(d.blocks),groups:clone(d.groups||[]),pageHeight:pageHeight(d)}];d.activePageId=id;}return d.pages;}
export function switchPage(d,id){ensurePages(d);syncPage(d);const p=d.pages.find(p=>p.id===id);if(!p)throw Error('Página não encontrada.');d.activePageId=p.id;d.blocks=clone(p.blocks);d.groups=clone(p.groups||[]);d.pageHeight=p.pageHeight||1431;}
export function addPage(d,name='Nova página'){ensurePages(d);if(d.pages.length>=20)throw Error('Limite de 20 páginas por ficha.');syncPage(d);const p={id:uid(),name,blocks:[],groups:[],pageHeight:1431};d.pages.push(p);switchPage(d,p.id);return p;}
export function deletePage(d,id){const index=d.pages?.findIndex(p=>p.id===id)??-1;if(index<0)throw Error('Página não encontrada.');if(d.pages.length<=1)throw Error('A ficha precisa ter pelo menos uma página.');syncPage(d);const [removed]=d.pages.splice(index,1);if(d.activePageId===id){const next=d.pages[Math.min(index,d.pages.length-1)];d.activePageId=next.id;d.blocks=clone(next.blocks);d.groups=clone(next.groups||[]);d.pageHeight=next.pageHeight||1431;}return removed;}
export function pageDocuments(d){const copy=clone(d);syncPage(copy);if(!copy.pages?.length)return [copy];return copy.pages.map(p=>{const result={...copy,blocks:clone(p.blocks),groups:clone(p.groups||[]),pageHeight:p.pageHeight||1431,pageName:p.name};delete result.pages;delete result.activePageId;return result;});}
export function economicDocument(d){const copy=clone(d);copy.background='#ffffff';copy.accent='#252525';copy.noTexture=true;copy.economicPrint=true;copy.theme={...copy.theme,text:'#202020',secondary:'#333333',frame:'simple'};for(const b of copy.blocks){b.color='#333333';b.textColor='#202020';if(b.textStyle)b.textStyle={...b.textStyle,color:'#202020',shadow:false};if(b.titleStyle)b.titleStyle={...b.titleStyle,color:'#333333'};if(b.richText)for(const r of b.richText.ranges||[])r.style={...r.style,color:'#202020',shadow:false};}return copy;}
export function growBlock(d,b,skills=[]){const bottom=b.y+b.h,next=Math.max(b.h,requiredHeight(b,d,skills)),delta=Math.min(4000,next)-b.h;b.h+=delta;b.autoFit=false;if(d.flowMode==='flow')for(const other of d.blocks)if(other!==b&&other.y>=bottom-1&&other.x<b.x+b.w&&other.x+other.w>b.x)other.y+=delta;d.pageHeight=Math.min(20000,Math.max(pageHeight(d),...d.blocks.map(x=>x.y+x.h+80)));return next<=4000;}
// Continuations contain snapshots of the selected text. The source retains its complete character data.
export function continueText(d,b,text,skills=[],measure=null){if(!String(text).trim())throw Error('Este bloco não possui texto para continuar.');if(b.richText?.ranges?.length)throw Error('Remova a formatação parcial antes de repartir o texto; ela será preservada na ficha original.');const chunks=[],words=String(text).match(/\S+\s*/g)||[],probe={...b,type:'text',part:'content',autoFit:false,h:1100,w:Math.min(b.w,1680)};let current='';const height=t=>measure?measure({...probe,body:t},d):requiredHeight({...probe,body:t},d,skills);for(const word of words){if(current&&height(current+word)>1050){chunks.push(current);current=word;}else current+=word;}if(current)chunks.push(current);ensurePages(d);if(d.pages.length+chunks.length>20)throw Error('A continuação ultrapassaria o limite de 20 páginas.');const original=d.activePageId;for(let i=0;i<chunks.length;i++){addPage(d,(b.title||'Texto')+' · '+(i+1));const part=block('text',(b.title||'Texto')+' · continuação '+(i+1),120,160,probe.w,1100,{body:chunks[i],autoFit:false,textStyle:clone(b.textStyle||{}),font:b.font,align:b.align});d.blocks.push(part);}syncPage(d);switchPage(d,original);b=d.blocks.find(x=>x.id===b.id);b.continuation=true;b.visible=false;syncPage(d);return chunks.length;}
export function versionSummary(before,after){if(!before)return 'Primeiro estado salvo';const changes=[];for(const [key,label] of [['name','nome'],['profile','perfil'],['equipment','inventário'],['pv','PV'],['pd','PD']])if(before[key]!==after[key])changes.push(label);if(JSON.stringify(before.skills)!==JSON.stringify(after.skills))changes.push('perícias');if(JSON.stringify(before.abilities)!==JSON.stringify(after.abilities))changes.push('habilidades');if(JSON.stringify(before.rituals)!==JSON.stringify(after.rituals))changes.push('rituais');if(JSON.stringify(before.blocks)!==JSON.stringify(after.blocks))changes.push('composição');if((before.pages?.length||1)!==(after.pages?.length||1))changes.push('páginas');return changes.length?'Alterações: '+changes.join(', '):'Estado preservado';}
export function saveContentItem(kind,title,body,fields={}){if(!['ability','ritual','weapon','equipment'].includes(kind)||!String(title).trim())throw Error('Informe tipo e nome do item.');return {id:uid(),kind:'content',name:String(title).trim(),contentKind:kind,body:String(body),fields:clone(fields)};}
export function insertContent(d,item){const k=item.contentKind,f=item.fields||{};let b;if(k==='ability'){const a={id:uid(),semanticId:'content:'+item.id,title:item.name,body:item.body};d.abilities.push(a);b=block('ability',a.title,1150,Math.max(300,...d.blocks.map(x=>x.y+x.h+28)),625,225,{ref:a.id,autoFit:false});}else if(k==='ritual'){const r={...clone(f),id:uid(),title:item.name,body:item.body,summary:f.summary||item.body,meta:f.meta||''};d.rituals.push(r);b=block('ritualPart',r.title,1150,Math.max(300,...d.blocks.map(x=>x.y+x.h+28)),625,225,{ref:r.id,field:'summary',showTitle:true,autoFit:false});}else if(k==='weapon'){d.weapon=item.name;d.weaponNote=item.body;d.damage=f.damage==='RB'?'RB':'RA';d.attackSkill=f.attackSkill==='Pontaria'?'Pontaria':'Luta';d.equipment+=(d.equipment?'\n':'')+item.name+': '+item.body;b=block('equipment','Equipamento',1150,800,625,250);}else{d.equipment+=(d.equipment?'\n':'')+item.name+': '+item.body;b=block('equipment','Equipamento',1150,800,625,250);}d.blocks.push(b);growBlock(d,b);return b;}
